pub(crate) const STYLES: &str = r#"
.df-campaign{--gold:#dfb974;--muted:#b6bec6;--ink:#070d14;position:relative;isolation:isolate;min-height:100svh;background:var(--ink);color:#f5eee0;font-family:Georgia,'Times New Roman',serif;overflow:hidden}
.df-campaign *{box-sizing:border-box}.df-campaign .scene-art{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center;z-index:-3}.df-campaign:before{content:'';position:absolute;inset:0;z-index:-2;background:linear-gradient(180deg,rgba(3,8,15,.58),transparent 28%,rgba(3,8,15,.14) 45%,#070d14 100%),linear-gradient(90deg,rgba(5,10,17,.35),transparent 60%)}
.df-campaign .topbar{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:27px 4vw;border-bottom:1px solid #dbc18b26;background:#08111b55}.df-campaign .brand{font-size:31px;letter-spacing:-1.3px;color:#f3d59d}.df-campaign .brand span{color:#b9d8e9}.df-campaign .overline{font:10px/1.7 system-ui,sans-serif;letter-spacing:2.5px;text-transform:uppercase;color:var(--gold)}
.df-campaign .preview-badge{font:10px/1.5 system-ui,sans-serif;text-transform:uppercase;letter-spacing:1.4px;border:1px solid #bda16866;border-radius:3px;padding:9px 13px;color:#e5c992;background:#08111ba8}.df-campaign .toolbar{display:flex;flex-wrap:wrap;gap:5px}.df-campaign button{font:12px system-ui,sans-serif;letter-spacing:.5px;min-height:44px;color:#d2d5d5;background:#0a1425aa;border:1px solid #9aa9b638;border-radius:3px;padding:10px 16px;cursor:pointer}.df-campaign button:hover,.df-campaign button[aria-pressed=true]{color:#f0d59b;border-color:#c6a568;background:#6b502441}.df-campaign button:focus-visible{outline:2px solid #9ddbff;outline-offset:4px}
.df-campaign .stage{width:min(1520px,92vw);margin:0 auto;min-height:570px;display:grid;grid-template-columns:1fr 280px;gap:8vw;align-items:end;padding:100px 0 42px}.df-campaign .chapter{font:11px system-ui,sans-serif;color:#e4c88c;letter-spacing:3px;text-transform:uppercase;margin:0 0 22px;display:flex;align-items:center;gap:16px}.df-campaign .chapter:before{content:'';width:47px;height:1px;background:var(--gold)}
.df-campaign h1{font-weight:400;font-size:clamp(45px,5.5vw,88px);line-height:1.05;letter-spacing:-2px;max-width:800px;margin:0 0 24px;text-shadow:0 3px 35px #000}.df-campaign .description{font-size:20px;line-height:1.7;color:#ddd8cc;max-width:600px;margin:0}.df-campaign .location{font:11px system-ui,sans-serif;letter-spacing:1.8px;text-transform:uppercase;margin-top:30px;color:#a5c2d2}.df-campaign .location:before{content:'◇';margin-right:12px;color:var(--gold)}
.df-campaign .scene-panel{background:linear-gradient(140deg,#0c1721e8,#08101ce8);border:1px solid #a993614d;border-radius:4px;padding:27px;box-shadow:0 20px 55px #0005}.df-campaign h2{font-size:23px;font-weight:400;line-height:1.35;margin:8px 0 23px}.df-campaign .objectives{list-style:none;margin:0;padding:0}.df-campaign .objective{font:12px/1.7 system-ui,sans-serif;color:#acb5bf;padding:14px 0 14px 25px;position:relative;border-top:1px solid #b6b3a015}.df-campaign .objective:before{content:'○';position:absolute;left:0;color:#788691;font-size:18px;line-height:20px}.df-campaign .objective[data-state=active]{color:#f0d9ad}.df-campaign .objective[data-state=active]:before{color:#f4c16d;content:'◉';text-shadow:0 0 14px #ffc66b}.df-campaign .objective[data-state=complete]:before{content:'✓';color:#9cc7ad}
.df-campaign .lower{width:min(1520px,92vw);margin:0 auto;padding:0 0 35px;display:grid;grid-template-columns:1fr 340px;gap:28px;align-items:start}.df-campaign .narration{display:flex;gap:24px;align-items:center;padding:25px 28px;border:1px solid #ad925d55;border-radius:4px;background:linear-gradient(105deg,#111b27ee,#070e18ee);position:relative}.df-campaign .narration:before{content:'✦';position:absolute;top:-11px;left:50%;background:#0d1520;padding:0 14px;color:var(--gold);font-size:15px}.df-campaign .narrator{height:76px;width:76px;flex-shrink:0;border-radius:50%;border:1px solid #d1b67c;object-fit:cover}.df-campaign blockquote{margin:12px 0 0;font-size:19px;line-height:1.65;color:#d4d4d0;font-style:italic}.df-campaign .party-heading{display:flex;align-items:baseline;justify-content:space-between;margin:0 0 15px}.df-campaign .party{display:grid;gap:8px}.df-campaign .party-card{display:flex;gap:14px;align-items:center;border:1px solid #8a9bae33;border-radius:3px;background:#0b1524db;padding:12px 15px}.df-campaign .sigil{width:39px;height:39px;display:grid;place-items:center;border:1px solid #bc9e6355;color:#d8bc7c;font:13px Georgia,serif;transform:rotate(45deg);flex-shrink:0}.df-campaign .sigil span{transform:rotate(-45deg)}.df-campaign .member-name{font-size:16px;line-height:1.5}.df-campaign .member-role{font:10px/1.6 system-ui,sans-serif;color:#a7b4c1}.df-campaign .connection{font:10px/1.6 system-ui,sans-serif;color:#8a99a8;letter-spacing:.6px;padding:0 4vw 22px;text-align:center}
.df-campaign .art-gallery{width:min(1520px,92vw);margin:0 auto 40px;border-top:1px solid #b69b6355;padding-top:30px}.df-campaign .art-gallery summary{font-size:23px;color:#dfbd80;cursor:pointer;min-height:44px}.df-campaign .gallery-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;padding-top:25px}.df-campaign .gallery-card{margin:0;background:#0d1827;border:1px solid #a0a9b32b}.df-campaign .gallery-card img{width:100%;aspect-ratio:16/9;object-fit:cover;display:block}.df-campaign .gallery-card figcaption{padding:13px 16px;font:11px/1.7 system-ui,sans-serif;color:#bac4ce}.df-campaign .gallery-card a{color:#dfbd80;text-decoration:none}.df-campaign .gallery-card a:hover{text-decoration:underline}
@media(min-width:1600px){.df-campaign .stage{min-height:650px}}@media(max-width:1000px){.df-campaign .topbar{flex-wrap:wrap;gap:18px}.df-campaign .stage{gap:30px;padding-top:90px;grid-template-columns:1fr 250px}.df-campaign .lower{grid-template-columns:1fr 280px}.df-campaign .narration{gap:17px;padding:22px}.df-campaign blockquote{font-size:17px}.df-campaign .narrator{width:60px;height:60px}}
@media(max-width:700px){.df-campaign .topbar{padding:20px 5vw}.df-campaign .brand{font-size:27px}.df-campaign .preview-badge{font-size:8px;padding:7px}.df-campaign .toolbar{width:100%}.df-campaign button{flex:1;padding:10px 8px}.df-campaign .stage{display:block;min-height:0;padding-top:120px;width:90vw}.df-campaign h1{letter-spacing:-1px;font-size:49px}.df-campaign .description{font-size:17px}.df-campaign .scene-panel{margin-top:35px;padding:22px}.df-campaign .lower{display:flex;flex-direction:column;width:90vw;gap:28px}.df-campaign .narration{align-items:start;padding:22px 18px;gap:14px}.df-campaign .narrator{width:46px;height:46px}.df-campaign blockquote{font-size:16px}.df-campaign .party-section{width:100%}.df-campaign .party{grid-template-columns:1fr}.df-campaign .gallery-grid{grid-template-columns:1fr}.df-campaign .scene-art{height:700px;object-position:40% center}.df-campaign:before{background:linear-gradient(180deg,#03080f80,transparent 15%,#070d14 640px)}}
"#;
